def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    bands = []
    start = None
    for r in range(h):
        active = any(v != bg for v in grid[r])
        if active and start is None:
            start = r
        elif not active and start is not None:
            bands.append((start, r))
            start = None
    if start is not None:
        bands.append((start, h))

    out = [row[:] for row in grid]
    if len(bands) < 2:
        return out

    (a0, a1), (b0, b1) = bands[:2]
    height = min(a1 - a0, b1 - b0)

    # The second band is a horizontally shifted copy of the first.
    best_shift, best_score = 0, -1
    for shift in range(-4, 5):
        matches = total = 0
        for k in range(height):
            for c in range(w):
                d = c + shift
                if 0 <= d < w:
                    matches += ((grid[a0 + k][c] != bg) ==
                                (grid[b0 + k][d] != bg))
                    total += 1
        score = matches / total if total else 0
        if score > best_score:
            best_score, best_shift = score, shift

    # Mark missing cells in either copy according to the alignment.
    for k in range(height):
        for c in range(w):
            d = c + best_shift
            if not 0 <= d < w:
                continue
            upper = grid[a0 + k][c]
            lower = grid[b0 + k][d]
            if upper != bg and lower == bg:
                out[b0 + k][d] = 1
            elif lower != bg and upper == bg:
                out[a0 + k][c] = 1

    return out
